# ---------------------------------------------------------------- D-AY03 지역 축제 매칭 (조건 넷, 120가지 전수 조사)
FES = {'가': (50, 40, 20), '나': (30, 70, 15), '다': (20, 80, 12), '라': (40, 45, 10), '마': (25, 60, 30)}   # 방문객(만 명), 외지인 비율(%), 예산(억 원)
out = lambda k: F(FES[k][0] * FES[k][1], 100)
ppb = lambda k: F(FES[k][2] * 10 ** 8, FES[k][0] * 10 ** 4)                                             # 방문객 1명당 예산(원)
unique_max({k: out(k) for k in FES}, 'D-AY03'); unique_max({k: ppb(k) for k in FES}, 'D-AY03'); unique_max({k: v[1] for k, v in FES.items()}, 'D-AY03')
NM = ['갑', '을', '병', '정', '무']
CON3 = [lambda m: out(m['갑']) == max(out(k) for k in FES), lambda m: ppb(m['을']) == max(ppb(k) for k in FES), lambda m: FES[m['병']][1] == max(v[1] for v in FES.values()), lambda m: ppb(m['정']) < ppb(m['무'])]
def sols3(cs): return [m for m in (dict(zip(NM, pm)) for pm in itertools.permutations(FES)) if all(c(m) for c in cs)]
